const carSizes = require('./car-sizes.json');

function getCarSize(customerHeight) {
  let minHeight = Infinity;
  let maxHeight = -Infinity;

  for (let size in carSizes) {
    const heightRange = carSizes[size].heightRange.split(' - ');

    // Convert inches to feet and convert strings to numbers
    const minFeet = parseInt(heightRange[0].slice(0, -3)) * 12 + parseInt(heightRange[0].slice(-2));
    const maxFeet = parseInt(heightRange[1].slice(0, -3)) * 12 + parseInt(heightRange[1].slice(-2));

    minHeight = Math.min(minHeight, minFeet);
    maxHeight = Math.max(maxHeight, maxFeet);

    if (customerHeight >= minFeet && customerHeight <= maxFeet) {
      return size;
    }
  }

  throw new Error(`Customer height ${customerHeight} does not fall within any of the allowed ranges`);
}

