Here's an implementation of Bubble Sort in C++ for your given JSON array:

```cpp
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp>

namespace json = nlohmann;

// Bubble Sort algorithm
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = true;

    // Loop through all elements to sort
    while (swapped) {
        swapped = false;

        // Last i elements are already in place
        for (int I = 0; I < n-1; i++) {
            if (arr[i] > arr[i+1]) {
                // Swap arr[i] and arr[i+1]
                int temp = arr[i];
                arr[i] = arr[i+1];
                arr[i+1] = temp;
                swapped = true;
            }
        }

        // If no two adjacent elements were swapped, then the list is sorted
        --n;
    }
}

// Parse JSON object containing array and apply bubble sort
